steps.codeExample:
trait Resumivel {
    fn resumo(&self) -> String;
}

struct Artigo { titulo: String }

impl Resumivel for Artigo {
    fn resumo(&self) -> String {
        format!("Artigo: {}", self.titulo)
    }
}

fn imprimir_resumo<T: Resumivel>(item: &T) {
    println!("{}", item.resumo());
}

